CREATE TABLE IF NOT EXISTS reports (id TEXT PRIMARY KEY, identity_mode TEXT NOT NULL, reporter_name TEXT NOT NULL, contact TEXT NOT NULL, reporter_level TEXT NOT NULL, category TEXT NOT NULL, subject TEXT NOT NULL, location TEXT NOT NULL, incident_date DATE NOT NULL, urgency TEXT NOT NULL, description TEXT NOT NULL, evidence TEXT NOT NULL DEFAULT '-', status TEXT NOT NULL DEFAULT 'Baru', feedback TEXT NOT NULL DEFAULT 'Aduan sudah masuk dan menunggu verifikasi polisi taruna.', history JSONB NOT NULL DEFAULT '[]'::jsonb, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS mentor_notes (id BIGSERIAL PRIMARY KEY, report_id TEXT NOT NULL, note TEXT NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
